## Feat: providers

- Added `atomProvider` function
- Added `filterProvider` function

Both functions accept a dictionary with atoms and filters respectively and return a hook that accepts one string argument (the key of an atom/filter) and returns the state of that atom/filter as `useAtom` or `useFilter` would.

Example:

```tsx
import { atom, filter, atomProvider, filterProvider } from 'atomic-state'

const textState = atom({
  name: 'text',
  default: ''
})

const countState = atom({
  name: 'count',
  default: 0
})

const doubleState = filter({
  name: 'double',
  get({ get }) {
    const count = get(countState)
    const text = get(textState)
    return `${count * 2} - ${text}`
  }
})

// A hook for all of our atoms
const useAppAtom = atomProvider({
  text: textState,
  count: countState
})

// A hook for all of our filters
const useAppFilter = filterProvider({
  double: doubleState
})

export default function Page() {

  // Type is inferred as 'string'
  const [text, setText] = useAppAtom('text')

  // Type is inferred as 'number'
  const [count, setCount] = useAppAtom('count')

  // Type is inferred as 'string'
  const double = useAppFilter('double')

  return (
    <div>
      <input type='text' value={text} onChange={e => setText(e.target.value)} />
      <button onClick={() => setCount(count + 1)}>{count}</button>
      <p>{double}</p>
    </div>
  )
}

```

